#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;
    vector<long long> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];
    sort(A.begin(), A.end());

    vector<long long> cost(N, 0);
    for (int i = 1; i < N; ++i) {
        long long d = A[i] - A[i - 1];
        cost[i] = d * d;
    }

    const long long INF = 4e18;
    vector<long long> dp(N, INF);

    int high1 = N - 3 * K + 1;
    for (int i = 1; i <= high1; ++i) {
        dp[i] = cost[i];
    }

    for (int r = 2; r <= K; ++r) {
        vector<long long> pref(N, INF);
        pref[0] = dp[0];
        for (int i = 1; i < N; ++i) {
            pref[i] = min(pref[i - 1], dp[i]);
        }

        vector<long long> ndp(N, INF);
        int low = 2 * r - 1;
        int high = N - 3 * K + 3 * r - 2;

        for (int i = low; i <= high; ++i) {
            if (i >= 2) {
                ndp[i] = cost[i] + pref[i - 2];
            }
        }
        dp.swap(ndp);
    }

    long long ans = INF;
    int lowK = 2 * K - 1;
    int highK = N - 2;
    for (int i = lowK; i <= highK; ++i) {
        ans = min(ans, dp[i]);
    }

    cout << ans << '\n';
    return 0;
}
